/** The stage is drawn at 350 × 372 and scaled to fit, between these (spec §4.1). */
const STAGE_W = 350;
const STAGE_FIT_H = 384;
const STAGE_MAX = 1.35;
const STAGE_MIN = 0.55;

/** The stage's scale for the space it has. */
export function stageScale(width: number, height: number): number {
  return Math.max(STAGE_MIN, Math.min(STAGE_MAX, height / STAGE_FIT_H, (width - 16) / STAGE_W));
}
