/**
 * One clock per story scene (onboarding v2 spec §12). Every animation of a
 * scene is a Web Animation created paused, and they all move together:
 * play, pause and seek act on the whole set, so Pause, a reduced-motion
 * final frame and a test's "what is on screen at 7 s" are exact. Text that
 * changes (a count, a typed letter, a label) is a cue: a function run once
 * the clock passes its time. One requestAnimationFrame loop reads the
 * clock, and only while it plays.
 *
 * The clock itself is the scene's progress segment filling up (linear, the
 * scene's length), which is what the learner sees time by.
 */

/**
 * Cancelling an animation rejects its `finished` promise; a scene cancels
 * its animations whenever it leaves, which is not an error.
 */
export function quiet(animation: Animation): Animation {
  void animation.finished.catch(() => undefined);
  return animation;
}

/** Whether this browser has Web Animations. Without them a scene shows its last frame. */
export function canAnimate(): boolean {
  return typeof Element !== 'undefined' && typeof Element.prototype.animate === 'function';
}

interface Cue {
  at: number;
  run: () => void;
  done: boolean;
}

export class SceneClock {
  private readonly anims: Animation[] = [];
  private cues: Cue[] = [];
  private readonly driver: Animation | undefined;
  private frame = 0;
  private last = -1;
  private playing = false;
  /** Set by the story: called once when the clock reaches the end while playing. */
  onFinish: (() => void) | undefined;

  constructor(
    readonly duration: number,
    bar: HTMLElement | null,
  ) {
    if (canAnimate() && bar !== null) {
      this.driver = quiet(
        bar.animate([{ transform: 'scaleX(0)' }, { transform: 'scaleX(1)' }], {
          duration,
          fill: 'both',
          easing: 'linear',
        }),
      );
      this.driver.pause();
      this.driver.onfinish = () => {
        this.playing = false;
        this.runCues(this.duration);
        this.onFinish?.();
      };
    }
  }

  /** A paused animation on the clock. Nothing happens without Web Animations. */
  add(element: Element | null | undefined, frames: Keyframe[], options: KeyframeAnimationOptions): void {
    if (element === null || element === undefined || this.driver === undefined) return;
    const animation = quiet(element.animate(frames, { fill: 'both', ...options }));
    animation.pause();
    animation.currentTime = this.time();
    this.anims.push(animation);
  }

  /** Runs `run` once the clock passes `at` milliseconds (and again after a seek back). */
  cue(at: number, run: () => void): void {
    this.cues.push({ at, run, done: false });
  }

  /** Where the clock is, in milliseconds. */
  time(): number {
    const now = this.driver?.currentTime;
    return typeof now === 'number' ? now : this.last < 0 ? 0 : this.last;
  }

  isPlaying(): boolean {
    return this.playing;
  }

  /** Whether the clock has reached its end. */
  ended(): boolean {
    return this.time() >= this.duration;
  }

  play(): void {
    if (this.driver === undefined) {
      this.seek(this.duration);
      return;
    }
    if (this.ended()) return;
    this.playing = true;
    for (const animation of this.anims) animation.play();
    this.driver.play();
    this.loop();
  }

  pause(): void {
    this.playing = false;
    cancelAnimationFrame(this.frame);
    for (const animation of this.anims) animation.pause();
    this.driver?.pause();
    this.runCues(this.time());
  }

  /** Puts every animation and cue at `ms` and stays paused there. */
  seek(ms: number): void {
    this.playing = false;
    cancelAnimationFrame(this.frame);
    const at = Math.max(0, Math.min(this.duration, ms));
    for (const animation of this.anims) {
      animation.pause();
      animation.currentTime = at;
    }
    if (this.driver !== undefined) {
      this.driver.pause();
      this.driver.currentTime = at;
    }
    this.runCues(at);
  }

  /** Cancels everything: the scene is leaving the screen. */
  dispose(): void {
    this.playing = false;
    this.onFinish = undefined;
    cancelAnimationFrame(this.frame);
    for (const animation of this.anims) animation.cancel();
    this.anims.length = 0;
    this.driver?.cancel();
    this.cues = [];
  }

  private loop(): void {
    cancelAnimationFrame(this.frame);
    const tick = (): void => {
      if (!this.playing) return;
      this.runCues(this.time());
      this.frame = requestAnimationFrame(tick);
    };
    this.frame = requestAnimationFrame(tick);
  }

  private runCues(time: number): void {
    // Back in time (a seek to the start): every cue may run again, in order.
    if (time < this.last) for (const cue of this.cues) cue.done = false;
    for (const cue of this.cues) {
      if (!cue.done && cue.at <= time) {
        cue.done = true;
        cue.run();
      }
    }
    this.last = time;
  }
}

/** A layout box inside the unscaled stage: where something sits before the stage's scale. */
export function placeIn(
  element: Element,
  stage: HTMLElement,
): { x: number; y: number; w: number; h: number } {
  const scale = Number.parseFloat(getComputedStyle(stage).getPropertyValue('--stage-scale')) || 1;
  const box = element.getBoundingClientRect();
  const frame = stage.getBoundingClientRect();
  return {
    x: (box.left - frame.left) / scale,
    y: (box.top - frame.top) / scale,
    w: box.width / scale,
    h: box.height / scale,
  };
}

/** The house curves, by name (tokens.css), for Web Animations, which take no custom properties. */
export const EASE = {
  out: 'cubic-bezier(0.32, 0.72, 0, 1)',
  emph: 'cubic-bezier(0.05, 0.7, 0.1, 1)',
  spring: 'cubic-bezier(0.2, 0.8, 0.2, 1)',
  fly: 'cubic-bezier(0.45, 0, 0.2, 1)',
} as const;
