import { t } from '@/i18n/index.js';
import { EASE, type SceneClock } from './sceneClock.js';
import { SAMPLE_CARD, SAMPLE_MEANINGS } from './sample.js';

/** One letter every 60 ms, from 300 ms (spec §4.1, scene 2). */
const TYPE_FROM_MS = 300;
const TYPE_EVERY_MS = 60;
/** The meaning line changes language at these moments: DE → ES → FA → JA → DE. */
const SWAP_AT_MS = [6200, 7450, 8700, 9950] as const;
const SWAP_ORDER = [1, 2, 3, 0] as const;

/** Lays scene 2's motion on its clock. */
export function buildScene2(stage: HTMLElement, clock: SceneClock): void {
  const one = (name: string): HTMLElement | null => stage.querySelector<HTMLElement>(`[data-${name}]`);
  const hw = one('hw');
  const caret = one('caret');
  const skel = one('skel');
  const body = one('body');
  const ai = one('ai');
  const code = one('lang');
  const meaning = one('tword');
  if (
    hw === null ||
    caret === null ||
    skel === null ||
    body === null ||
    ai === null ||
    code === null ||
    meaning === null
  )
    return;
  const show = (language: number): void => {
    const sample = SAMPLE_MEANINGS[language] ?? SAMPLE_MEANINGS[0];
    code.textContent = sample.code;
    meaning.textContent = sample.text;
    meaning.lang = sample.lang;
    meaning.dir = sample.lang === 'fa' ? 'rtl' : 'ltr';
  };
  const word = SAMPLE_CARD.word;
  clock.cue(0, () => {
    hw.textContent = '';
    caret.hidden = false;
    skel.hidden = true;
    body.hidden = true;
    ai.textContent = t('onb.s2.writing');
    show(0);
  });
  Array.from(word).forEach((_, index) => {
    clock.cue(TYPE_FROM_MS + index * TYPE_EVERY_MS, () => {
      hw.textContent = word.slice(0, index + 1);
    });
  });
  clock.cue(1050, () => {
    caret.hidden = true;
    skel.hidden = false;
  });
  clock.cue(2500, () => {
    skel.hidden = true;
    body.hidden = false;
    ai.textContent = t('onb.s2.written');
  });
  const rise = (element: Element | null | undefined, delay: number): void => {
    clock.add(
      element,
      [
        { opacity: 0, transform: 'translateY(8px)' },
        { opacity: 1, transform: 'none' },
      ],
      {
        delay,
        duration: 420,
        easing: EASE.emph,
      },
    );
  };
  Array.from(one('meta')?.children ?? []).forEach((part, index) => {
    rise(part, 2500 + index * 60);
  });
  rise(one('mean'), 2900);
  rise(one('num'), 2900);
  rise(one('trans'), 3300);
  rise(one('ex'), 3700);
  Array.from(one('colls')?.children ?? []).forEach((part, index) => {
    rise(part, 4300 + index * 70);
  });
  SWAP_AT_MS.forEach((swapAt, index) => {
    clock.add(
      meaning,
      [
        { opacity: 1, transform: 'none' },
        { opacity: 0, transform: 'translateY(-6px)', offset: 0.35 },
        { opacity: 0, transform: 'translateY(6px)', offset: 0.5 },
        { opacity: 1, transform: 'none' },
      ],
      { delay: swapAt, duration: 420, easing: EASE.out, fill: 'forwards' },
    );
    clock.cue(swapAt + 180, () => {
      show(SWAP_ORDER[index] ?? 0);
    });
  });
  clock.add(
    one('saved'),
    [
      { opacity: 0, transform: 'scale(.6)' },
      { opacity: 1, transform: 'scale(1.06)', offset: 0.7 },
      { opacity: 1, transform: 'scale(1)' },
    ],
    { delay: 11400, duration: 380, easing: EASE.spring },
  );
}
