import { t } from '@/i18n/index.js';
import { EASE, placeIn, type SceneClock } from './sceneClock.js';
import { SAMPLE_WORDS } from './sample.js';

/** Each source's share of the scene: three sources in 12 s (spec §4.1). */
const SOURCE_MS = 3900;
/** The first source starts a moment after the page lands. */
const FIRST_SOURCE_MS = 200;
/** How far an older notebook row steps down when a new one lands on top. */
const ROW_STEP_PX = 39;

const at = (x: number, y: number, s = 1): string =>
  `translate(${String(x)}px, ${String(y)}px) scale(${String(s)})`;

/** Lays scene 1's motion on its clock (spec §4.1, the table under Scene 1). */
export function buildScene1(stage: HTMLElement, clock: SceneClock): void {
  const all = (name: string): HTMLElement[] =>
    Array.from(stage.querySelectorAll<HTMLElement>(`[data-${name}]`));
  const sources = all('src');
  const marks = all('hl');
  const flies = all('fly');
  const rows = all('row');
  const tip = stage.querySelector<HTMLElement>('[data-tip]');
  const tap = stage.querySelector<HTMLElement>('[data-tap]');
  const count = stage.querySelector<HTMLElement>('[data-count]');
  const rowsBox = stage.querySelector<HTMLElement>('[data-rows]');
  if (tip === null || tap === null || count === null || rowsBox === null) return;

  const say = (n: number): void => {
    count.textContent = t('onb.s1.words', { count: n });
  };
  clock.cue(0, () => {
    say(0);
  });
  // Where things sit, read once: every source shares one box, so the marks
  // are laid out even while their source is still faded out.
  const places = marks.map((one) => placeIn(one, stage));
  const shelf = placeIn(rowsBox, stage);

  SAMPLE_WORDS.forEach((_, k) => {
    const start = k * SOURCE_MS + FIRST_SOURCE_MS;
    const source = sources[k];
    const place = places[k];
    if (source === undefined || place === undefined) return;
    if (k === 0) {
      clock.add(
        source,
        [
          { opacity: 0, transform: 'translateY(14px)' },
          { opacity: 1, transform: 'none' },
        ],
        {
          delay: 0,
          duration: 520,
          easing: EASE.emph,
        },
      );
    } else {
      clock.add(
        sources[k - 1],
        [
          { opacity: 1, transform: 'none' },
          { opacity: 0, transform: 'translateY(-10px) scale(.98)' },
        ],
        { delay: start - FIRST_SOURCE_MS, duration: 320, easing: EASE.out, fill: 'forwards' },
      );
      clock.add(
        source,
        [
          { opacity: 0, transform: 'translateY(14px)' },
          { opacity: 1, transform: 'none' },
        ],
        {
          delay: start,
          duration: 460,
          easing: EASE.emph,
        },
      );
    }
    // The marker sweeps over the word.
    clock.add(marks[k], [{ backgroundSize: '0% 100%' }, { backgroundSize: '100% 100%' }], {
      delay: start + 700,
      duration: 520,
      easing: EASE.out,
    });
    // "Save to Lexpad" above the word, a tap on it, then it goes.
    const tipX = Math.min(350 - 130, Math.max(0, place.x + place.w / 2 - 62));
    const first = k === 0 ? 'both' : 'forwards';
    clock.add(
      tip,
      [
        { opacity: 0, transform: at(tipX, place.y - 40, 0.9) },
        { opacity: 1, transform: at(tipX, place.y - 42) },
      ],
      {
        delay: start + 1300,
        duration: 220,
        easing: EASE.spring,
        fill: first,
      },
    );
    clock.add(
      tip,
      [
        { opacity: 1, transform: at(tipX, place.y - 42) },
        { opacity: 0, transform: at(tipX, place.y - 46, 0.96) },
      ],
      {
        delay: start + 2250,
        duration: 180,
        fill: 'forwards',
      },
    );
    clock.add(
      tap,
      [
        { opacity: 0, transform: at(tipX + 44, place.y - 44, 0.5) },
        { opacity: 0.9, transform: at(tipX + 44, place.y - 44, 1), offset: 0.4 },
        { opacity: 0, transform: at(tipX + 44, place.y - 44, 1.35) },
      ],
      { delay: start + 1850, duration: 460, fill: first },
    );
    // The word lifts, arcs over the top and lands on the notebook's first row.
    const x0 = place.x - 10;
    const y0 = place.y - 4;
    const x1 = shelf.x + 4;
    const y1 = shelf.y;
    clock.add(
      flies[k],
      [
        { opacity: 0, transform: at(x0, y0, 0.96) },
        { opacity: 1, transform: at(x0, y0 - 6, 1.06), offset: 0.12 },
        {
          opacity: 1,
          transform: at((x0 + x1) / 2 + 30, Math.min(y0, y1) - 40, 1.04),
          offset: 0.55,
          easing: EASE.fly,
        },
        { opacity: 1, transform: at(x1, y1, 0.94), offset: 0.92 },
        { opacity: 0, transform: at(x1, y1, 0.94) },
      ],
      { delay: start + 2250, duration: 900, easing: EASE.fly },
    );
    // The row lands on top; the older ones step down and dim.
    const land = start + 3080;
    clock.add(
      rows[k],
      [
        { opacity: 0, transform: 'translateY(-6px)' },
        { opacity: 1, transform: 'translateY(0)' },
      ],
      {
        delay: land,
        duration: 260,
        easing: EASE.emph,
      },
    );
    for (let j = 0; j < k; j++) {
      const from = (k - 1 - j) * ROW_STEP_PX;
      const to = (k - j) * ROW_STEP_PX;
      clock.add(
        rows[j],
        [
          { transform: `translateY(${String(from)}px)`, opacity: 1 },
          { transform: `translateY(${String(to)}px)`, opacity: to > ROW_STEP_PX * 1.5 ? 0.55 : 0.85 },
        ],
        { delay: land - 40, duration: 300, easing: EASE.out, fill: 'forwards' },
      );
    }
    clock.cue(land, () => {
      say(k + 1);
    });
  });
}
