/**
 * Where "Watch a 30-second tour" plays from (onboarding v2 spec §9).
 *
 * Today the three files ship with the app, in `public/tour/` (the review
 * build's choice, 22 Oct 2026: media.lexpad.app does not exist yet). The
 * service worker does not precache them (its patterns take no mp4, vtt or
 * webp), and the video is fetched only once the learner presses play
 * (`preload="none"`; only the poster loads with the layer).
 *
 * To move them to media.lexpad.app (R2, hashed immutable keys, Range), set
 * `VITE_TOUR_MEDIA_BASE` to that folder's address (ending in `/`) and, in the
 * same change, add `media-src https://media.lexpad.app` (and the host to
 * `img-src` for the poster) to the Content-Security-Policy in vite.config.ts.
 * A new cut is a new file name (`tour-v3…`), never the same name replaced.
 */

/** The file names of the current cut. */
export const TOUR_FILES = {
  video: 'tour-v2.mp4',
  captions: 'tour-v2.vtt',
  poster: 'tour-v2-poster.webp',
} as const;

/** The folder the tour is served from, ending in `/`. */
export function tourBase(env: Record<string, unknown> = import.meta.env): string {
  const set = env.VITE_TOUR_MEDIA_BASE;
  if (typeof set === 'string' && set.trim() !== '') return set.endsWith('/') ? set : `${set}/`;
  const base = typeof env.BASE_URL === 'string' ? env.BASE_URL : '/';
  return `${base.endsWith('/') ? base : `${base}/`}tour/`;
}

/** The three addresses the player needs. */
export function tourMedia(base = tourBase()): { video: string; captions: string; poster: string } {
  return {
    video: `${base}${TOUR_FILES.video}`,
    captions: `${base}${TOUR_FILES.captions}`,
    poster: `${base}${TOUR_FILES.poster}`,
  };
}

/** The spoken words of a WebVTT file, cue by cue, for the transcript. */
export function transcriptOf(vtt: string): string[] {
  const blocks = vtt.replace(/\r\n?/g, '\n').split(/\n{2,}/);
  const lines: string[] = [];
  for (const block of blocks) {
    const rows = block.split('\n');
    const timing = rows.findIndex((row) => row.includes('-->'));
    if (timing < 0) continue;
    const text = rows
      .slice(timing + 1)
      .join(' ')
      .replace(/<[^>]*>/g, '')
      .replace(/\s+/g, ' ')
      .trim();
    if (text !== '') lines.push(text);
  }
  return lines;
}
