import { memo, useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Icon } from '@/components/ui/Icon.js';
import { prefersReducedMotion } from '@/components/ui/motionPrefs.js';
import { t, type MessageKey } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { platform } from '@/lib/platform/index.js';
import mark from './marks/lexpad-mark-v1.svg';
import { countIntroStep } from './introSteps.js';
import { markIntroSeen } from './seen.js';
import { EASE, SceneClock, canAnimate, quiet } from './story/sceneClock.js';
import { stageScale } from './story/stage.js';
import { Scene1 } from './story/Scene1.js';
import { buildScene1 } from './story/motion1.js';
import { Scene2 } from './story/Scene2.js';
import { buildScene2 } from './story/motion2.js';
import { Scene3 } from './story/Scene3.js';
import { buildScene3 } from './story/motion3.js';
import { TourPlayer } from './TourPlayer.js';
import scenes from './story/Scenes.module.css';
import styles from './Story.module.css';

interface Page {
  /** Static markup: memoised, so a page change re-renders none of the drawings. */
  Scene: React.MemoExoticComponent<() => React.JSX.Element>;
  build: (stage: HTMLElement, clock: SceneClock) => void;
  /** How long the scene plays before the story moves on (spec §4.1: 12, 13, 13 s). */
  duration: number;
  pill: MessageKey;
  title1: MessageKey;
  title2: MessageKey;
  sub: MessageKey;
  alt: MessageKey;
}

const PAGES: readonly Page[] = [
  {
    Scene: memo(Scene1),
    build: buildScene1,
    duration: 12_000,
    pill: 'onb.s1.pill',
    title1: 'onb.s1.title1',
    title2: 'onb.s1.title2',
    sub: 'onb.s1.sub',
    alt: 'onb.s1.alt',
  },
  {
    Scene: memo(Scene2),
    build: buildScene2,
    duration: 13_000,
    pill: 'onb.s2.pill',
    title1: 'onb.s2.title1',
    title2: 'onb.s2.title2',
    sub: 'onb.s2.sub',
    alt: 'onb.s2.alt',
  },
  {
    Scene: memo(Scene3),
    build: buildScene3,
    duration: 13_000,
    pill: 'onb.s3.pill',
    title1: 'onb.s3.title1',
    title2: 'onb.s3.title2',
    sub: 'onb.s3.sub',
    alt: 'onb.s3.alt',
  },
];
const LAST = PAGES.length - 1;

/** A page change (spec §4.1): the old page goes −28% and fades, the new one comes in from 100%. */
const PAGE_MS = 420;
const PAGE_OUT = 28;
/** Under reduced motion pages cross-fade instead. */
const FADE_MS = 200;
/** A swipe: 40 px, or a flick of 0.3 px a millisecond. */
const SWIPE_PX = 40;
const FLICK_PX_PER_MS = 0.3;
/** Whether focus arrived by keyboard (`:focus-visible`); a browser without the selector says no. */
function focusedByKeyboard(element: HTMLElement): boolean {
  try {
    return element.matches(':focus-visible');
  } catch {
    return false;
  }
}

function isRtl(): boolean {
  return document.documentElement.dir === 'rtl';
}

/**
 * The first thing a stranger sees (onboarding v2, uiux 2026-10-21 spec §4.1):
 * three short animated stories on the forest ground — you meet a word, AI
 * writes the card, the word comes back before you forget. Each plays once,
 * holds its last frame and moves on; Pause, Skip, swipe, the arrow keys and
 * Continue all work, and the last page never moves into the questions by
 * itself. Nothing here talks to the network: the card is a drawing, and AI
 * never runs before an account.
 */
export function Story(): React.JSX.Element {
  const navigate = useNavigate();
  const location = useLocation();
  const from = (location.state as { from?: unknown } | null)?.from;
  const [reduced] = useState(() => prefersReducedMotion() || !canAnimate());
  const [index, setIndex] = useState(0);
  const [paused, setPaused] = useState(false);
  const [tour, setTour] = useState(false);
  const [leaving, setLeaving] = useState<{ page: number; dir: 1 | -1 } | undefined>(undefined);
  const [running, setRunning] = useState(false);

  const root = useRef<HTMLDivElement>(null);
  const stageBoxes = useRef<(HTMLDivElement | null)[]>([]);
  const stages = useRef<(HTMLDivElement | null)[]>([]);
  const pages = useRef<(HTMLElement | null)[]>([]);
  const fills = useRef<(HTMLElement | null)[]>([]);
  const headlines = useRef<(HTMLHeadingElement | null)[]>([]);
  const clock = useRef<SceneClock | undefined>(undefined);
  const outgoing = useRef<SceneClock | undefined>(undefined);
  const pausedNow = useRef(false);
  const firstPage = useRef(true);
  const indexNow = useRef(0);

  const toQuestions = useCallback((): void => {
    clock.current?.pause();
    void navigate('/intro/learn', { state: { from } });
  }, [navigate, from]);

  /** Moves to another page; `own` is a learner's action (a tick), never the auto-advance. */
  const go = useCallback(
    (next: number, own: boolean): void => {
      const now = indexNow.current;
      if (next > LAST) {
        if (own) toQuestions();
        return;
      }
      if (next < 0 || next === now) return;
      if (own) platform.haptics.tick();
      outgoing.current?.dispose();
      outgoing.current = clock.current;
      outgoing.current?.pause();
      clock.current = undefined;
      indexNow.current = next;
      setLeaving({ page: now, dir: next > now ? 1 : -1 });
      setIndex(next);
    },
    [toQuestions],
  );

  useEffect(() => {
    countIntroStep('open');
  }, []);

  // The scene's end reads the latest `go` without rebuilding the scene.
  const goNow = useRef(go);
  useEffect(() => {
    goNow.current = go;
  });

  const pause = useCallback((): void => {
    pausedNow.current = true;
    setPaused(true);
    clock.current?.pause();
    setRunning(false);
  }, []);

  const resume = useCallback((): void => {
    pausedNow.current = false;
    setPaused(false);
    const current = clock.current;
    if (current === undefined || reduced) return;
    // A scene that already ended moves on, as its own end would have.
    if (current.ended()) {
      if (indexNow.current < LAST) go(indexNow.current + 1, false);
      return;
    }
    current.play();
    setRunning(true);
  }, [go, reduced]);

  // The stage fills the space it has, as one scaled drawing (CLS 0).
  useLayoutEffect(() => {
    const box = stageBoxes.current[index];
    const story = root.current;
    if (box === null || box === undefined || story === null) return undefined;
    const fit = (): void => {
      const { width, height } = box.getBoundingClientRect();
      if (width === 0 || height === 0) return;
      story.style.setProperty('--stage-scale', String(stageScale(width, height)));
    };
    fit();
    if (typeof ResizeObserver !== 'function') return undefined;
    const observer = new ResizeObserver(fit);
    observer.observe(box);
    return () => {
      observer.disconnect();
    };
  }, [index]);

  // Each page builds its scene on its own clock when it comes on screen.
  useLayoutEffect(() => {
    const stage = stages.current[index];
    const page = PAGES[index];
    if (stage === null || stage === undefined || page === undefined) return undefined;
    fills.current.forEach((fill, k) => {
      if (fill) fill.dataset.done = k < index ? '1' : '0';
    });
    const scene = new SceneClock(page.duration, fills.current[index] ?? null);
    page.build(stage, scene);
    scene.onFinish = () => {
      setRunning(false);
      if (!reduced && !pausedNow.current && indexNow.current === index && index < LAST)
        goNow.current(index + 1, false);
    };
    clock.current = scene;
    if (reduced) {
      // Reduced motion: the finished frame, and no auto-advance.
      scene.seek(page.duration);
    } else if (pausedNow.current || document.visibilityState === 'hidden') {
      scene.seek(0);
    } else {
      scene.play();
      setRunning(true);
    }
    return () => {
      // A scene leaving with a page change is kept until its page has slid away.
      if (outgoing.current !== scene) scene.dispose();
    };
  }, [index, reduced]);

  // The page change itself, and focus to the new page's headline.
  useLayoutEffect(() => {
    if (leaving === undefined) return undefined;
    const before = pages.current[leaving.page];
    const after = pages.current[index];
    const done = (): void => {
      outgoing.current?.dispose();
      outgoing.current = undefined;
      setLeaving(undefined);
    };
    if (before === null || before === undefined || after === null || after === undefined || !canAnimate()) {
      done();
      return undefined;
    }
    const dir = leaving.dir * (isRtl() ? -1 : 1);
    const out = reduced
      ? before.animate([{ opacity: 1 }, { opacity: 0 }], {
          duration: FADE_MS,
          easing: 'linear',
          fill: 'both',
        })
      : before.animate(
          [
            { transform: 'none', opacity: 1 },
            { transform: `translateX(${String(-dir * PAGE_OUT)}%)`, opacity: 0 },
          ],
          { duration: PAGE_MS, easing: EASE.out, fill: 'both' },
        );
    const into = reduced
      ? after.animate([{ opacity: 0 }, { opacity: 1 }], { duration: FADE_MS, easing: 'linear' })
      : after.animate([{ transform: `translateX(${String(dir * 100)}%)` }, { transform: 'none' }], {
          duration: PAGE_MS,
          easing: EASE.out,
        });
    quiet(out);
    quiet(into);
    out.onfinish = done;
    return () => {
      out.onfinish = null;
      out.cancel();
      into.cancel();
    };
  }, [leaving, index, reduced]);

  useEffect(() => {
    if (firstPage.current) {
      firstPage.current = false;
      return;
    }
    headlines.current[index]?.focus({ preventScroll: true });
  }, [index]);

  // Pause when the app goes to the background, and when keyboard focus
  // moves into the page (WCAG 2.2.2): moving content never fights a reader.
  useEffect(() => {
    const onVisibility = (): void => {
      if (document.visibilityState === 'hidden' && !pausedNow.current) pause();
    };
    const onFocus = (event: FocusEvent): void => {
      const target = event.target;
      if (!(target instanceof HTMLElement) || pausedNow.current) return;
      if (target.dataset.storyControl !== undefined || target.tagName === 'H1') return;
      if (focusedByKeyboard(target)) pause();
    };
    const story = root.current;
    document.addEventListener('visibilitychange', onVisibility);
    story?.addEventListener('focusin', onFocus);
    return () => {
      document.removeEventListener('visibilitychange', onVisibility);
      story?.removeEventListener('focusin', onFocus);
    };
  }, [pause]);

  // The arrow keys turn the pages, mirrored in a right-to-left layout.
  useEffect(() => {
    if (tour) return undefined;
    const onKey = (event: KeyboardEvent): void => {
      if (event.altKey || event.ctrlKey || event.metaKey) return;
      if (event.key !== 'ArrowRight' && event.key !== 'ArrowLeft') return;
      const forward = (event.key === 'ArrowRight') !== isRtl();
      go(indexNow.current + (forward ? 1 : -1), true);
    };
    window.addEventListener('keydown', onKey);
    return () => {
      window.removeEventListener('keydown', onKey);
    };
  }, [go, tour]);

  // The status bar's icons stay light over the forest ground in both themes
  // (read by the shells' system-bar style, lib/platform).
  useEffect(() => {
    const html = document.documentElement;
    html.dataset.bars = 'light';
    return () => {
      delete html.dataset.bars;
    };
  }, []);

  useEffect(
    () => () => {
      clock.current?.dispose();
      outgoing.current?.dispose();
    },
    [],
  );

  // A swipe: horizontal wins over vertical, 40 px or a flick.
  const swipe = useRef<{ x: number; y: number; at: number } | undefined>(undefined);
  const onPointerDown = (event: React.PointerEvent): void => {
    swipe.current = { x: event.clientX, y: event.clientY, at: performance.now() };
  };
  const onPointerUp = (event: React.PointerEvent): void => {
    const start = swipe.current;
    swipe.current = undefined;
    if (start === undefined) return;
    const dx = event.clientX - start.x;
    const dy = event.clientY - start.y;
    const speed = Math.abs(dx) / Math.max(1, performance.now() - start.at);
    if (Math.abs(dx) <= Math.abs(dy)) return;
    if (Math.abs(dx) < SWIPE_PX && speed < FLICK_PX_PER_MS) return;
    const forward = dx < 0 !== isRtl();
    go(indexNow.current + (forward ? 1 : -1), true);
  };

  return (
    <div ref={root} className={cx(styles.story, paused && styles.paused)} data-running={running ? '1' : '0'}>
      <section className={styles.body} aria-roledescription="carousel" aria-label={t('onb.storyLabel')}>
        <div className={styles.bars} aria-hidden="true">
          {PAGES.map((_, k) => (
            <div key={k} className={styles.bar}>
              <i
                className={styles.fill}
                ref={(element) => {
                  fills.current[k] = element;
                }}
              />
            </div>
          ))}
        </div>
        <header className={styles.top}>
          <span className={styles.brand}>
            <img src={mark} alt="" width={28} height={28} />
            {t('app.name')}
          </span>
          <span className={styles.topEnd}>
            {!reduced && (
              <button
                type="button"
                className={styles.iconButton}
                data-story-control=""
                aria-label={paused ? t('onb.play') : t('onb.pause')}
                onClick={() => {
                  if (paused) resume();
                  else pause();
                }}
              >
                <Icon name={paused ? 'play' : 'pause'} size={18} weight={2} />
              </button>
            )}
            <button type="button" className={styles.skip} data-story-control="" onClick={toQuestions}>
              {t('onb.skip')}
            </button>
          </span>
        </header>
        <p className="sr-only" aria-live="polite">
          {t('onb.screenOf', { n: index + 1 })}
        </p>
        <div className={styles.pages} onPointerDown={onPointerDown} onPointerUp={onPointerUp}>
          {PAGES.map((page, k) => (
            <article
              key={k}
              ref={(element) => {
                pages.current[k] = element;
              }}
              className={styles.page}
              // Every page stays laid out, only out of sight: showing one is
              // then a compositor change, not a first layout of its whole
              // scene in the frame the page starts to slide (spec §12).
              data-off={k !== index && leaving?.page !== k ? '' : undefined}
              inert={k !== index}
              aria-hidden={k !== index}
              aria-roledescription="slide"
              aria-labelledby={`story-h${String(k)}`}
            >
              <div
                className={styles.stageBox}
                ref={(element) => {
                  stageBoxes.current[k] = element;
                }}
              >
                <div
                  className={scenes.stage}
                  role="img"
                  aria-label={t(page.alt)}
                  ref={(element) => {
                    stages.current[k] = element;
                  }}
                >
                  <page.Scene />
                </div>
              </div>
              <div className={styles.copy}>
                <span className={styles.pill}>{t(page.pill)}</span>
                <h1
                  id={`story-h${String(k)}`}
                  className={styles.headline}
                  tabIndex={-1}
                  ref={(element) => {
                    headlines.current[k] = element;
                  }}
                >
                  {t(page.title1)} <em>{t(page.title2)}</em>
                </h1>
                <p className={styles.sub}>{t(page.sub)}</p>
                <button
                  type="button"
                  className={styles.tour}
                  data-story-control=""
                  tabIndex={k === index ? 0 : -1}
                  onClick={() => {
                    pause();
                    setTour(true);
                  }}
                >
                  <span className={styles.disc} aria-hidden="true">
                    <Icon name="play" size={14} />
                  </span>
                  {t('onb.tour')}
                </button>
              </div>
            </article>
          ))}
        </div>
        <div className={styles.actions}>
          <button
            type="button"
            className={styles.primary}
            data-story-control=""
            onClick={() => {
              go(index + 1, true);
            }}
          >
            {index === LAST ? t('onb.makePlan') : t('onb.continue')}
          </button>
          <button
            type="button"
            className={styles.ghost}
            data-story-control=""
            onClick={() => {
              clock.current?.pause();
              markIntroSeen();
              void navigate('/auth', { state: { from } });
            }}
          >
            {t('onb.haveAccount')}
          </button>
        </div>
      </section>
      {tour && (
        <TourPlayer
          onClose={() => {
            // Back to the story, paused: the learner picks up when ready.
            setTour(false);
          }}
        />
      )}
    </div>
  );
}
