import { INTERVALS } from '@lexpad/core';
import { t } from '@/i18n/index.js';
import { EASE, type SceneClock } from './sceneClock.js';
import { reviewDays, waitLabel } from './sample.js';

/*
 * The chart (spec §4.1, scene 3). The days are Lexpad's real review days for
 * a word answered right each time (INTERVALS); the heights are an
 * illustration, and the stage's alt text says so.
 */
/** The axis ends a few days past the last review, so the flat tail shows. */
export const AXIS_DAYS = 36;
/** The chart's drawing box (viewBox 318 × 176). */
export const CHART_W = 318;
const LEFT = 14;
const SPAN = 298;
export const TOP = 18;
export const BOTTOM = 150;
/** A review comes when memory has decayed to 60%: S = gap / −ln 0.6. */
const DECAY_TO = 0.6;
/** "Without reviews": the classic forgetting curve, e^(−t / 1.96). */
const NO_REVIEW_S = 1.96;
/** After the last review the line is nearly flat. */
const SETTLED_S = 140;
/** Steps per drawn segment: smooth at any scale, cheap to draw. */
const SEGMENT_STEPS = 28;
const NO_REVIEW_STEPS = 60;
/** The green line: each interval revealed in 1000 ms, then 650 ms held at the review. */
const REVEAL_FROM_MS = 2000;
const REVEAL_MS = 1000;
const HOLD_MS = 650;
/** Box width: (350 − 4 gaps of 6) / 5. */
const BOX_W = (350 - 24) / 5;
const BOX_GAP = 6;

export const x = (day: number): number => LEFT + SPAN * Math.sqrt(day / AXIS_DAYS);
export const y = (strength: number): number => BOTTOM - (BOTTOM - TOP) * strength;
export const f = (value: number): string => value.toFixed(1);

/** The two curves and the area under Lexpad's, as SVG paths. */
export function curvePaths(reviews: readonly number[]): { lexpad: string; without: string; area: string } {
  const k = -Math.log(DECAY_TO);
  let lexpad = `M${f(x(0))} ${f(y(1))}`;
  const starts = [0, ...reviews];
  starts.forEach((from, index) => {
    const to = reviews[index] ?? AXIS_DAYS;
    const s = index < reviews.length ? (to - from) / k : SETTLED_S;
    for (let step = 1; step <= SEGMENT_STEPS; step++) {
      const day = from + ((to - from) * step) / SEGMENT_STEPS;
      lexpad += ` L${f(x(day))} ${f(y(Math.exp(-(day - from) / s)))}`;
    }
    if (index < reviews.length) lexpad += ` L${f(x(to))} ${f(y(1))}`;
  });
  let without = `M${f(x(0))} ${f(y(1))}`;
  for (let step = 1; step <= NO_REVIEW_STEPS; step++) {
    const day = (AXIS_DAYS * step) / NO_REVIEW_STEPS;
    without += ` L${f(x(day))} ${f(y(Math.exp(-day / NO_REVIEW_S)))}`;
  }
  return { lexpad, without, area: `${lexpad} L${f(x(AXIS_DAYS))} ${f(BOTTOM)} L${f(x(0))} ${f(BOTTOM)} Z` };
}

/** Lays scene 3's motion on its clock. */
export function buildScene3(stage: HTMLElement, clock: SceneClock): void {
  const all = (name: string): Element[] => Array.from(stage.querySelectorAll(`[data-${name}]`));
  const boxes = all('box') as HTMLElement[];
  const labels = all('day');
  const dots = all('dot');
  const rings = all('ring');
  const chip = stage.querySelector('[data-chip]');
  const lastWait = boxes[boxes.length - 1]?.querySelector('[data-wait]');
  const reviews = reviewDays();
  // A right-to-left page lays the boxes out from the right.
  const rtl = getComputedStyle(stage).direction === 'rtl';
  const centre = (index: number): number => {
    const left = BOX_W / 2 + index * (BOX_W + BOX_GAP);
    return rtl ? 350 - left : left;
  };
  const chipAt = (index: number, lift = 0): string =>
    `translateX(${f(centre(index))}px) translateX(-50%) translateY(${String(lift)}px)`;

  clock.cue(0, () => {
    boxes.forEach((box, index) => {
      if (index === 0) box.dataset.state = 'lit';
      else delete box.dataset.state;
    });
    for (const label of labels) delete (label as SVGElement).dataset.on;
    if (lastWait) lastWait.textContent = waitLabel(INTERVALS[INTERVALS.length - 1] ?? 0);
  });
  // "Without reviews" draws left to right first.
  clock.add(
    stage.querySelector('[data-clip-without]'),
    [{ transform: 'scaleX(0)' }, { transform: 'scaleX(1)' }],
    {
      delay: 300,
      duration: 1500,
      easing: EASE.out,
    },
  );
  // Lexpad's line advances one interval at a time and waits at each review.
  const ends = [...reviews.map((day) => x(day) / CHART_W), 1];
  const total = ends.length * (REVEAL_MS + HOLD_MS);
  const frames: Keyframe[] = [{ transform: 'scaleX(0)', offset: 0, easing: EASE.fly }];
  let time = 0;
  for (const end of ends) {
    time += REVEAL_MS;
    frames.push({ transform: `scaleX(${String(end)})`, offset: time / total, easing: EASE.fly });
    time += HOLD_MS;
    frames.push({ transform: `scaleX(${String(end)})`, offset: Math.min(1, time / total) });
  }
  clock.add(stage.querySelector('[data-clip-with]'), frames, { delay: REVEAL_FROM_MS, duration: total });
  clock.add(chip, [{ transform: chipAt(0) }, { transform: chipAt(0) }], { duration: 1 });
  reviews.forEach((_, index) => {
    const reached = REVEAL_FROM_MS + (index + 1) * REVEAL_MS + index * HOLD_MS;
    clock.add(
      dots[index],
      [
        { opacity: 0, transform: 'scale(.3)' },
        { opacity: 1, transform: 'scale(1)' },
      ],
      {
        delay: reached,
        duration: 320,
        easing: EASE.spring,
      },
    );
    clock.add(
      rings[index],
      [
        { opacity: 0, transform: 'scale(1)' },
        { opacity: 0.7, transform: 'scale(1)', offset: 0.02 },
        { opacity: 0, transform: 'scale(2.6)' },
      ],
      { delay: reached, duration: 700, easing: EASE.out },
    );
    clock.add(
      chip,
      [
        { transform: chipAt(index) },
        { transform: chipAt(index + 1, -6), offset: 0.6 },
        { transform: chipAt(index + 1) },
      ],
      { delay: reached + 80, duration: 460, easing: EASE.emph, fill: 'forwards' },
    );
    clock.cue(reached + 200, () => {
      const box = boxes[index + 1];
      if (box) box.dataset.state = index + 1 === boxes.length - 1 ? 'gold' : 'lit';
      const label = labels[index] as SVGElement | undefined;
      if (label) label.dataset.on = '1';
    });
  });
  const mastered = REVEAL_FROM_MS + total - 300;
  clock.cue(mastered, () => {
    if (lastWait) lastWait.textContent = t('onb.s3.mastered');
  });
  clock.add(
    boxes[boxes.length - 1],
    [{ transform: 'scale(1)' }, { transform: 'scale(1.06)', offset: 0.5 }, { transform: 'scale(1)' }],
    { delay: mastered, duration: 420, easing: EASE.spring, fill: 'forwards' },
  );
}
