import { useId } from 'react';
import { INTERVALS } from '@lexpad/core';
import { t } from '@/i18n/index.js';
import { BOTTOM, CHART_W, TOP, curvePaths, x, y } from './motion3.js';
import { SAMPLE_CARD, reviewDays, waitLabel } from './sample.js';
import styles from './Scenes.module.css';

/** Scene 3, "It comes back before you forget.": the curve and the five boxes. */
export function Scene3(): React.JSX.Element {
  const id = useId().replace(/:/g, '');
  const reviews = reviewDays();
  const { lexpad, without, area } = curvePaths(reviews);
  const last = reviews[reviews.length - 1];
  return (
    <>
      <div className={`${styles.card} ${styles.ccard}`}>
        <div className={styles.chead}>
          <h4>{t('onb.s3.chart')}</h4>
          <div className={styles.legend}>
            <span>
              <i />
              {t('onb.s3.with')}
            </span>
            <span>
              <i className={styles.dash} />
              {t('onb.s3.without')}
            </span>
          </div>
        </div>
        <svg className={styles.chart} viewBox={`0 0 ${String(CHART_W)} 176`} aria-hidden="true">
          <defs>
            <clipPath id={`${id}w`}>
              <rect className={styles.clip} data-clip-with="" x="0" y="0" width={CHART_W} height="176" />
            </clipPath>
            <clipPath id={`${id}o`}>
              <rect className={styles.clip} data-clip-without="" x="0" y="0" width={CHART_W} height="176" />
            </clipPath>
          </defs>
          <line className={styles.grid} x1="12" y1={TOP} x2="312" y2={TOP} />
          <line className={styles.grid} x1="12" y1={BOTTOM} x2="312" y2={BOTTOM} />
          <text className={styles.yl} x="12" y="12">
            {t('onb.s3.strong')}
          </text>
          <text className={styles.yl} x="12" y="166">
            {t('onb.s3.day', { n: 0 })}
          </text>
          <path className={styles.without} d={without} clipPath={`url(#${id}o)`} />
          <path className={styles.area} d={area} clipPath={`url(#${id}w)`} />
          <path className={styles.with} d={lexpad} clipPath={`url(#${id}w)`} />
          {reviews.map((day) => (
            <text
              key={day}
              data-day=""
              x={day === last ? x(day) + 12 : x(day)}
              y="166"
              textAnchor={day === last ? 'end' : 'middle'}
            >
              {t('onb.s3.day', { n: day })}
            </text>
          ))}
          {reviews.map((day) => (
            <g key={day}>
              <circle className={styles.ring} data-ring="" cx={x(day)} cy={y(1)} r="6" />
              <circle className={styles.dot} data-dot="" cx={x(day)} cy={y(1)} r="5.5" />
            </g>
          ))}
        </svg>
      </div>
      <div className={styles.boxes}>
        {INTERVALS.map((days, index) => (
          <div key={index} className={styles.box} data-box="">
            <b>{t('onboarding.box', { n: index + 1 })}</b>
            <span data-wait="">{waitLabel(days)}</span>
          </div>
        ))}
        <span className={styles.chip} data-chip="" data-moves="" lang="en">
          {SAMPLE_CARD.word}
        </span>
      </div>
    </>
  );
}
