/**
 * The words the three stories draw (onboarding v2 spec §4.1).
 *
 * These are a drawn illustration of what Lexpad does, not data: no learner
 * owns them, nothing saves them, and the card in scene 2 is fixed copy, not a
 * model's answer. AI never runs before an account exists. They live here as
 * named constants, beside the sentences in en.ts (`onb.s1.*`, `onb.s2.*`),
 * because a picture of a book needs a word in it.
 */
import { INTERVALS } from '@lexpad/core';
import { t } from '@/i18n/index.js';

/** The three words met in scene 1: a book, a web page, a film's subtitles. */
export const SAMPLE_WORDS = ['ephemeral', 'meticulous', 'nonchalant'] as const;

/** Scene 2's card, for the first of them. */
export const SAMPLE_CARD = {
  word: 'ephemeral',
  ipa: '/ɪˈfem(ə)rəl/',
  level: 'C1',
  collocations: ['ephemeral beauty', 'ephemeral fame'],
} as const;

/**
 * The meaning in four of the learner's possible languages, cycled on the
 * card: German, Spanish, Persian (right to left, in Vazirmatn) and Japanese.
 */
export const SAMPLE_MEANINGS = [
  { code: 'DE', lang: 'de', text: 'vergänglich' },
  { code: 'ES', lang: 'es', text: 'efímero' },
  { code: 'FA', lang: 'fa', text: 'زودگذر' },
  { code: 'JA', lang: 'ja', text: '儚い' },
] as const;

/** A sentence with a `{word}` slot, split around the word so the word can be marked. */
export function aroundWord(template: string): [string, string] {
  const at = template.indexOf('{word}');
  if (at < 0) return [template, ''];
  return [template.slice(0, at), template.slice(at + '{word}'.length)];
}

/**
 * The review days of a word answered right each time, from the engine's own
 * gaps: INTERVALS [0, 1, 3, 7, 21] added up are days 1, 4, 11 and 32.
 */
export function reviewDays(): number[] {
  const days: number[] = [];
  let day = 0;
  for (const gap of INTERVALS.slice(1)) {
    day += gap;
    days.push(day);
  }
  return days;
}

/** "today", "1 day", "3 days": how long a box waits, from INTERVALS. */
export function waitLabel(days: number): string {
  if (days === 0) return t('onboarding.intervalToday');
  if (days === 1) return t('onboarding.intervalOneDay');
  return t('onboarding.intervalDays', { n: days });
}
