import { useEffect, useId, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { tourMedia, transcriptOf } from './tourMedia.js';
import styles from './TourPlayer.module.css';

/**
 * "Lexpad in 30 seconds" (onboarding v2 spec §9): a full-screen black layer
 * with the voiced tour. It never plays by itself: the video starts only from
 * its own play button, captions are on by default, and the transcript is a
 * tap away. Closing stops the video and lets go of it (its source is
 * removed, so nothing keeps downloading), and focus goes back to the link
 * that opened it.
 */
export function TourPlayer({ onClose }: { onClose: () => void }): React.JSX.Element {
  const media = tourMedia();
  const titleId = useId();
  const layer = useRef<HTMLDivElement>(null);
  const closeButton = useRef<HTMLButtonElement>(null);
  const video = useRef<HTMLVideoElement>(null);
  const [transcript, setTranscript] = useState<string[] | 'loading' | 'failed' | undefined>(undefined);
  const close = useRef(onClose);
  useEffect(() => {
    close.current = onClose;
  });

  useEffect(() => {
    const opener = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    closeButton.current?.focus();
    const onKey = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') {
        event.stopPropagation();
        close.current();
        return;
      }
      if (event.key !== 'Tab' || layer.current === null) return;
      // Focus stays inside the layer while it is open.
      const stops = Array.from(
        layer.current.querySelectorAll<HTMLElement>('button, a[href], video[controls], [tabindex="0"]'),
      );
      const first = stops[0];
      const last = stops[stops.length - 1];
      if (first === undefined || last === undefined) return;
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };
    document.addEventListener('keydown', onKey, true);
    const overflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    const player = video.current;
    return () => {
      document.removeEventListener('keydown', onKey, true);
      document.body.style.overflow = overflow;
      if (player !== null) {
        player.pause();
        player.removeAttribute('src');
        for (const source of Array.from(player.querySelectorAll('source'))) source.removeAttribute('src');
        player.load();
      }
      opener?.focus({ preventScroll: true });
    };
  }, []);

  const showTranscript = (): void => {
    video.current?.pause();
    setTranscript('loading');
    void fetch(media.captions)
      .then((answer) => (answer.ok ? answer.text() : Promise.reject(new Error(String(answer.status)))))
      .then((text) => {
        setTranscript(transcriptOf(text));
      })
      .catch(() => {
        setTranscript('failed');
      });
  };

  return createPortal(
    <div ref={layer} className={styles.layer} role="dialog" aria-modal="true" aria-labelledby={titleId}>
      <div className={styles.top}>
        <h2 id={titleId} className={styles.title}>
          {t('onb.tour.title')}
        </h2>
        <button
          ref={closeButton}
          type="button"
          className={styles.close}
          aria-label={t('onb.tour.close')}
          onClick={onClose}
        >
          <Icon name="close" size={20} weight={2} />
        </button>
      </div>
      <div className={styles.body}>
        <video
          ref={video}
          className={styles.video}
          hidden={Array.isArray(transcript)}
          controls
          playsInline
          preload="none"
          crossOrigin="anonymous"
          poster={media.poster}
          aria-label={t('onb.tour.label')}
        >
          <source src={media.video} type="video/mp4" />
          <track kind="captions" srcLang="en" label="English" src={media.captions} default />
        </video>
        {Array.isArray(transcript) && (
          <div className={styles.transcript} tabIndex={0}>
            {transcript.map((line, index) => (
              <p key={index}>{line}</p>
            ))}
          </div>
        )}
        {transcript === 'failed' && (
          <p className={styles.failed} role="alert">
            {t('onb.tour.failed')}
          </p>
        )}
      </div>
      <p className={styles.foot}>
        {t('onb.tour.captions')}{' '}
        {Array.isArray(transcript) ? (
          <button
            type="button"
            className={styles.link}
            onClick={() => {
              setTranscript(undefined);
            }}
          >
            {t('onb.tour.video')}
          </button>
        ) : (
          <button
            type="button"
            className={styles.link}
            disabled={transcript === 'loading'}
            onClick={showTranscript}
          >
            {t('onb.tour.transcript')}
          </button>
        )}
      </p>
    </div>,
    document.body,
  );
}
